// n8n Code 节点：Normalize Model Answers
// 将不同模型回答整理成统一字段。若平台返回字段不同，修改 content 取值即可。
const content = $json.choices?.[0]?.message?.content || $json.data?.choices?.[0]?.message?.content || $json.answer || '';
return [{ json: { ...$json, answer: content, api_status: content ? 'success' : ($json.api_status || 'failed'), api_error: $json.api_error || '', latency_ms: $json.latency_ms || 0, estimated_input_tokens: $json.estimated_input_tokens || 0, estimated_output_tokens: $json.estimated_output_tokens || 0, estimated_cost: $json.estimated_cost || 0 } }];

// n8n Code 节点：Objective Rule Checks
function countText(t){ return String(t||'').replace(/\s+/g,'').length; }
function isJson(t){ try{ JSON.parse(String(t||'').trim()); return true; }catch(e){ return false; } }
function hasTable(t){ return /\|.+\|/.test(String(t||'')) && /---/.test(String(t||'')); }
return items.map(item=>{
  const r=item.json, c=r.objective_checks||{}, a=r.answer||'', errors=[]; let score=100;
  if(r.api_status==='failed'){errors.push('API 调用失败'); score-=100;}
  if(!a.trim()){errors.push('回答为空'); score-=30;}
  if(c.must_be_json && !isJson(a)){errors.push('JSON 不合法'); score-=25;}
  if(c.require_table && !hasTable(a)){errors.push('未输出 Markdown 表格'); score-=15;}
  if(c.max_words && countText(a)>c.max_words){errors.push('超出字数限制'); score-=10;}
  for(const w of (c.banned_words||[])){ if(a.includes(w)){errors.push(`包含禁用词：${w}`); score-=10;} }
  for(const f of (c.required_fields||[])){ if(!a.includes(f)){errors.push(`缺少必填字段：${f}`); score-=8;} }
  score=Math.max(0,score);
  return {json:{...r,objective_pass:errors.length===0,objective_score:score,objective_errors:errors}};
});

// n8n Code 节点：Parse Judge Result
function parseJson(text){ const raw=String(text||'').trim(); try{return JSON.parse(raw);}catch(e){} const m=raw.match(/\{[\s\S]*\}/); if(m){try{return JSON.parse(m[0]);}catch(e){}} return null; }
return items.map(item=>{ const r=item.json; const p=parseJson(r.judge_raw || r.answer || ''); if(!p){ return {json:{...r,total_score:0,error_type:'评分JSON解析失败',risk_level:'中',judge_reason:'评分模型未输出合法 JSON',product_recommendation:'不建议直接用于选型结论'}};} return {json:{...r,...p}}; });

// n8n Code 节点：Aggregate Results
const rows=items.map(i=>i.json); const map={};
for(const r of rows){ const k=r.provider||'unknown'; map[k] ||= {provider:k,model_id:r.model_id||'',rows:[],scenarios:{},errors:{},first_count:0}; map[k].rows.push(r); map[k].scenarios[r.scenario] ||= []; map[k].scenarios[r.scenario].push(Number(r.total_score||0)); const e=r.error_type||'无'; map[k].errors[e]=(map[k].errors[e]||0)+1; }
const byCase={}; for(const r of rows){ byCase[r.case_id] ||= []; byCase[r.case_id].push(r); }
for(const arr of Object.values(byCase)){ arr.sort((a,b)=>Number(b.total_score||0)-Number(a.total_score||0)); if(arr[0]&&map[arr[0].provider]) map[arr[0].provider].first_count++; }
const avg=a=>a.length?a.reduce((x,y)=>x+Number(y||0),0)/a.length:0;
const summary=Object.values(map).map(g=>{ const scores=g.rows.map(r=>Number(r.total_score||0)); const scen=Object.fromEntries(Object.entries(g.scenarios).map(([k,v])=>[k,Number(avg(v).toFixed(2))])); const sorted=Object.entries(scen).sort((a,b)=>b[1]-a[1]); return {provider:g.provider,model_id:g.model_id,average_score:Number(avg(scores).toFixed(2)),first_count:g.first_count,failure_rate:Number((g.rows.filter(r=>r.api_status==='failed').length/Math.max(1,g.rows.length)).toFixed(4)),avg_latency_ms:Number(avg(g.rows.map(r=>r.latency_ms||0)).toFixed(0)),high_risk_rate:Number((g.rows.filter(r=>r.risk_level==='高').length/Math.max(1,g.rows.length)).toFixed(4)),scenario_average:scen,common_error_type:Object.entries(g.errors).sort((a,b)=>b[1]-a[1])[0]?.[0]||'无',best_scenario:sorted[0]?.[0]||'',weakest_scenario:sorted.at(-1)?.[0]||'',product_recommendation:'结合场景平均分、失败率、延迟和高风险占比综合判断。'}; }).sort((a,b)=>b.average_score-a.average_score);
return [{json:{generated_at:new Date().toISOString(),summary,raw_count:rows.length}}];
